"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["58745"],{57988(e){e.exports=JSON.parse('{"id":"FIN-1404","slug":"economic-capital","term":"Economic Capital","also_known_as":[],"difficulty":"Advanced","definition":"Economic capital is the amount of capital an organisation, such as a bank or insurer, estimates it needs to cover unexpected losses from all its risks, at a chosen level of confidence, based on its own internal risk models.","explanation":["Losses can be divided into expected losses, which are anticipated and covered by pricing and provisions, and unexpected losses, which arise from bad outcomes. Economic capital is the buffer held against unexpected losses.","Organisations calculate economic capital by modelling their credit, market, operational, insurance and other risks, usually at a high confidence level consistent with their target credit rating. For example, a bank aiming for a strong rating might hold enough economic capital to survive losses that would occur only once in a thousand years or more on average.","Economic capital is used internally to understand risk, set limits, measure risk-adjusted performance and allocate capital between business lines. For example, a bank may compare the profit of each division with the economic capital it uses, to judge which activities earn adequate returns for their risk.","Economic capital differs from regulatory capital, which is the minimum amount required by regulators using prescribed rules. The two can differ significantly, because internal models may reflect an organisation\'s specific risks and diversification more precisely."],"note":"","total":1500,"prev":{"slug":"ebitda-margin","term":"EBITDA Margin"},"next":{"slug":"economic-growth","term":"Economic Growth"}}')}}]);